FUENTE_B = "Fuente B (declaración de un grupo de vecinos): Vecinos de Los Pinos reclaman por la nueva plaza: dicen que faltan bancas y luz. Según el grupo, solo 120 personas asistieron a la inauguración. La obra costó 50 millones de pesos."
COM_C = "Comunicado de la dirección del colegio: La Feria de Ciencias se realizará el jueves a las 15 horas en el patio. Participarán 24 proyectos de 6.º básico. La entrada es gratuita."
OPI_D = "Publicación de una apoderada después de la feria: «¡La feria de ciencias estuvo espectacular! Los proyectos eran increíbles y todo el colegio se divirtió.»"

L(OA7, 1,
  MAT,
  "Aprenderé a determinar quién es el emisor de un texto, cuál es su propósito y a quién dirige el mensaje, para evaluar críticamente la información que entrega.",
  ["Distingo hecho y opinión.", "Sé qué tipos de texto no literario existen."],
  ["Todo texto lo escribe alguien: el emisor es la persona o institución que produce el mensaje. El propósito es para qué lo escribe: informar, persuadir (convencer o invitar a comprar o a hacer algo), instruir (enseñar a hacer algo) o entretener. El destinatario o audiencia es a quién se dirige: vecinos, estudiantes, clientes, familias.",
   "Evaluar críticamente es no creerlo todo sin preguntar. Antes de aceptar la información, se pregunta: ¿quién lo dice?, ¿para qué lo dice?, ¿a quién se lo dice? Un aviso de la municipalidad informa a los vecinos; un anuncio publicitario busca convencer a posibles compradores. Conocer el propósito ayuda a juzgar con más cuidado lo que se afirma.",
   "Por ejemplo, un anuncio que dice «el jugo más rico del mundo» tiene como propósito persuadir; no entrega una prueba, sino una opinión. En cambio, un aviso de recolección de basura entrega datos que se pueden comprobar. Reconocer el emisor y su propósito es el primer paso para evaluar."],
  [("emisor", "persona o institución que produce un mensaje"), ("propósito", "para qué se escribe un texto"), ("destinatario", "persona o grupo a quien se dirige el mensaje"), ("persuadir", "tratar de convencer a alguien de algo")],
  [("Identificar emisor y destinatario", f"Lee: «{AVISO}» ¿Quién es el emisor y a quién va dirigido?",
    ["Busco quién informa: la Municipalidad de Valle Verde.", "Busco a quién habla: «a los vecinos».", "Emisor: la municipalidad; destinatario: los vecinos."],
    "Emisor: la Municipalidad de Valle Verde; destinatario: los vecinos"),
   ("Identificar el propósito", f"Lee: «{PUBLI}» ¿Cuál es el propósito?",
    ["El emisor es una empresa que vende jugos.", "Usa frases como «el más rico del mundo» y «20 % de descuento».", "Su propósito es persuadir de comprar."],
    "Persuadir para que compren el jugo")],
  [("Creer que todo texto informa.", "No se pregunta por el emisor.", "Pregunta quién lo dice y para qué."),
   ("Confundir destinatario con emisor.", "Se invierten los roles.", "El emisor escribe; el destinatario recibe.")],
  ([E(f"Lee: «{AVISO}» ¿Qué institución emite el mensaje?", "La Municipalidad de Valle Verde", "Es quien informa."),
    E("Si un texto busca convencerte de comprar, ¿su propósito es persuadir o informar solamente?", "Persuadir", "Intenta influir en tus decisiones."),
    E("¿Quién es el destinatario: quien recibe el mensaje o quien lo escribe?", "Quien recibe el mensaje", "Es la audiencia.")],
   [E(f"Lee: «{AVISO}» ¿Cuál es el propósito: informar a los vecinos o venderles algo?", "Informar a los vecinos", "Comunica un cambio en el servicio."),
    E(f"Con este texto: «{RECETA}» ¿cuál es el propósito: instruir o persuadir?", "Instruir", "Enseña a preparar algo paso a paso."),
    E(f"Con este texto: «{PUBLI}» ¿a quién se dirige: a posibles compradores o a la municipalidad?", "A posibles compradores", "Quiere convencerlos de que compren.")],
   [E(f"Lee: «{PARQUE}» ¿A quién se dirige principalmente: a quienes quieren visitar el parque o a quienes quieren comprar jugo?", "A quienes quieren visitar el parque", "Informa horarios y atractivos."),
    arith("Una empresa dice que el descuento es de 20 % y el jugo cuesta 1.000 pesos. ¿Cuántos pesos se descuentan?", "1000//5", "El 20 % de 1.000 equivale a su quinta parte."),
    E(f"En «{PUBLI}», ¿«el más rico del mundo» es un dato comprobable o una opinión?", "Una opinión", "Nadie puede comprobar que sea el más rico.")],
   [E(f"Compara «{AVISO}» y «{PUBLI}». ¿Cuál debes revisar con más cuidado antes de creer sus afirmaciones: el aviso municipal o el anuncio de jugos?", "El anuncio de jugos", "Su propósito es vender y puede exagerar."),
    E(f"En «{RECETA}», una lectora dice que el propósito es entretener. ¿Es la mejor respuesta?", "No", "El propósito principal es instruir.")],
   [E("Un mensaje del curso a las familias pide traer un cuaderno. ¿Quién es el emisor y quién el destinatario? Elige: «El curso emite, las familias reciben» o «Las familias emiten, el curso recibe».", "«El curso emite, las familias reciben»", "El curso escribe y las familias leen."),
    arith("Una municipalidad envía un aviso a 120 familias y 30 ya respondieron. ¿Cuántas faltan por responder?", "120-30", "Se restan las respuestas del total.")]),
  [E("Recibes por la puerta un volante que dice «¡Oferta imperdible! Compre dos y lleve tres». ¿Cuál es el propósito más probable: persuadir o instruir?", "Persuadir", "Busca que la gente compre.")],
  [E("¿Qué pregunta sirve para evaluar un texto: «¿quién lo dice?» o «¿de qué color es?»", "¿Quién lo dice?", "Identifica el emisor."),
   E("¿Un anuncio publicitario busca persuadir?", "Sí", "Intenta convencer de comprar."),
   E("¿El destinatario es la audiencia a quien se dirige el mensaje?", "Sí", "Es quien recibe el texto.")],
  ("Lee estos tres textos y completa para cada uno emisor, propósito y destinatario: A) «El club de lectura invita a los niños de 5.º y 6.º a una tarde de cuentos el viernes.» B) «Mezcla la masa y déjala reposar media hora.» C) «¡Compra hoy las mejores zapatillas del país!»",
   "A) Emisor: el club de lectura; propósito: invitar/informar; destinatario: niños de 5.º y 6.º. B) Emisor: quien escribe la receta; propósito: instruir; destinatario: quien cocina. C) Emisor: una tienda; propósito: persuadir; destinatario: posibles compradores.",
   ["identifica el emisor de cada texto", "propósito coherente", "destinatario correcto"], ["tabla con tres filas"], ["confundir emisor y destinatario", "propósito sin evidencia"], "Subraya en cada texto la frase que prueba el propósito."),
  "Busca un anuncio y un aviso en tu casa o calle y completa emisor, propósito y destinatario.",
  "Escribe dos mensajes breves con distinto propósito para la misma audiencia.")

L(OA7, 2,
  MAT,
  "Aprenderé a modelar cómo se evalúa un texto con tres preguntas: ¿quién lo emite?, ¿para qué? y ¿a quién se dirige?, y a usar esas respuestas para juzgar la información.",
  ["Reconozco emisor, propósito y destinatario.", "Distingo hecho y opinión."],
  ["Modelar una evaluación crítica es pensar en voz alta ante un texto. Se puede decir: «Este texto lo emite una empresa; su propósito es vender; me habla a mí como posible comprador; por eso debo comprobar si lo que afirma es real». Cada frase une la pregunta con una pista del texto.",
   "Algunas pistas ayudan. El emisor suele aparecer en la firma, el encabezado o la presentación. El propósito se descubre por los verbos y la intención: «invitamos», «compra», «mezcla», «informamos». El destinatario se ve en las palabras con que se dirige: «estimados vecinos», «estudiantes», «clientes».",
   "Con esas respuestas puedes decidir cuánta confianza darle a la información. Un comunicado oficial entrega datos que se pueden verificar; un anuncio de venta puede exagerar. Esto no quiere decir que mienta, sino que conviene comprobar con otras fuentes."],
  [("encabezado", "parte inicial de un texto donde aparece quién lo envía"), ("pista", "palabra o frase que ayuda a descubrir algo"), ("verificar", "comprobar que algo es cierto"), ("fuente", "origen de la información")],
  [("Modelar la evaluación", f"Lee: «{PUBLI}» Piensa en voz alta la evaluación.",
    ["Emisor: una empresa de jugos.", "Propósito: persuadir; veo «llévalo con 20 % de descuento».", "Debo comprobar si es «el más rico del mundo»: es una opinión."],
    "Una empresa que busca vender; hay que comprobar sus afirmaciones"),
   ("Pistas del destinatario", "Un texto comienza: «Estimadas familias de 6.º básico: les informamos que…». ¿A quién se dirige?",
    ["Busco las palabras de saludo.", "«Estimadas familias de 6.º básico».", "El destinatario son las familias de 6.º básico."],
    "A las familias de 6.º básico")],
  [("Evaluar el texto sin saber quién lo emite.", "Se lee sin mirar la firma.", "Busca el emisor en la firma o presentación."),
   ("Desconfiar de todo.", "Se cree que evaluar es dudar siempre.", "Evaluar es verificar con criterio, no dudar de todo.")],
  ([E(f"Lee: «{COM_C}» ¿Quién emite el comunicado?", "La dirección del colegio", "Aparece en el encabezado."),
    E("Si un texto dice «invitamos a todos los estudiantes», ¿qué destinatario tiene?", "Los estudiantes", "Menciona a quién invita."),
    E("¿El emisor suele aparecer en la firma o en el encabezado?", "Sí", "Ahí se presenta quien escribe.")],
   [E(f"Con este comunicado: «{COM_C}» ¿cuál es su propósito: informar o convencer de comprar?", "Informar", "Entrega fecha, hora y condiciones."),
    E(f"Con esta publicación: «{OPI_D}» ¿es una opinión o un comunicado oficial?", "Una opinión", "Expresa lo que la apoderada piensa."),
    E(f"En «{COM_C}» ¿a qué hora será la feria?", "A las 15 horas", "Dato escrito en el texto.")],
   [arith("Si los 24 proyectos se reparten por igual entre 4 salas, ¿cuántos proyectos hay en cada sala?", "24//4", "Se reparten los proyectos por igual."),
    E(f"Según «{OPI_D}», ¿cuál es el propósito más probable: compartir una opinión o dar instrucciones?", "Compartir una opinión", "Expresa su impresión."),
    E("Si un texto de empresa dice «somos los más rápidos», ¿qué conviene hacer antes de creerlo: verificar con otra fuente o creerlo?", "Verificar con otra fuente", "Es una afirmación de quien vende.")],
   [E(f"Compara «{COM_C}» y «{OPI_D}». ¿Cuál entrega datos para saber dónde es la feria?", "El comunicado de la dirección", "Dice que es en el patio."),
    E("Un compañero dice: «Como el texto es de la dirección, no hay que verificar nada». ¿Es un buen criterio?", "No", "Conviene verificar siempre los datos clave.")],
   [E("¿Cuántas preguntas centrales usa el modelo de evaluación de esta clase (quién lo emite, para qué y a quién se dirige)?", "3", "Son tres preguntas para evaluar un texto."),
    E("La feria dura 90 minutos y empieza a las 15:00. ¿A qué hora termina? Escríbela con el formato 16:30.", "16:30", "Noventa minutos son una hora y media: 15:00 + 1 h 30 min.")]),
  [E("Ves en tu sala un cartel: «Reunión de padres el martes a las 18 horas. Dirección». ¿Quién es el emisor: la dirección o los padres?", "La dirección", "Firma el aviso.")],
  [E("¿Verificar es comprobar con otras fuentes?", "Sí", "Así se evalúa si la información es confiable."),
   E("¿Una firma puede indicar el emisor?", "Sí", "Dice quién escribe."),
   E("¿Evaluar críticamente es dudar de todo?", "No", "Es verificar con criterio.")],
  ("Lee: «Estimados apoderados: les recordamos que la reunión del jueves comenzará a las 19 horas en el gimnasio. Se ruega puntualidad. Atentamente, dirección.» Piensa en voz alta: 1) emisor, 2) destinatario, 3) propósito, 4) un dato que puedes verificar.",
   "1) La dirección. 2) Los apoderados. 3) Informar y recordar la reunión. 4) La hora (19 horas) y el lugar (gimnasio), que puedo verificar preguntando en el colegio.",
   ["identifica el emisor", "identifica el destinatario", "propósito coherente", "dato verificable"], ["cuatro respuestas escritas"], ["confundir emisor y destinatario", "dato no verificable"], "Subraya en el texto la pista de cada respuesta."),
  "Evalúa un aviso de tu barrio con las tres preguntas y cuéntalo en voz alta.",
  "Escribe un aviso con emisor claro y pide a alguien que identifique el propósito.")

L(OA7, 3,
  MAT,
  "Aprenderé a seleccionar evidencia para evaluar si un texto entrega suficiente información para responder una pregunta o cumplir un propósito.",
  ["Identifico emisor y propósito.", "Extraigo información explícita."],
  ["Un texto puede ser claro y estar bien escrito, pero no tener la información que necesitas. Por eso, al evaluar, hay que preguntarse si el texto entrega suficiente información para responder una pregunta o cumplir un propósito. Si el dato está escrito, es suficiente; si falta, es insuficiente.",
   "El procedimiento es: 1) lee la pregunta o el propósito; 2) busca en el texto el dato que lo responde; 3) si lo encuentras, cita la frase como evidencia; 4) si no lo encuentras, di qué dato falta. Por ejemplo, el texto del parque dice los horarios, pero no el precio de la entrada; para saber el precio, falta información.",
   "Hay textos que parecen decir lo que buscas pero solo lo sugieren. Comprueba que el dato esté realmente escrito o que se pueda deducir con una pista clara. Si hay que adivinar, la información es insuficiente."],
  [("suficiente", "que alcanza para lo que se necesita"), ("insuficiente", "que no alcanza para lo que se necesita"), ("dato", "información precisa"), ("evidencia", "frase que respalda una respuesta")],
  [("Información suficiente", f"Lee: «{PARQUE}» Pregunta: ¿A qué hora abre el parque? ¿Alcanza la información?",
    ["Busco la hora de apertura.", "El texto dice «de 9 a 18 horas».", "Sí alcanza: abre a las 9."],
    "Sí, abre a las 9 horas"),
   ("Información insuficiente", f"Con el mismo texto: ¿Cuánto cuesta la entrada?",
    ["Busco el precio.", "No aparece en el texto.", "Es insuficiente: falta el precio de la entrada."],
    "No alcanza: falta el precio")],
  [("Responder con un dato que el texto no tiene.", "Se completa con lo que uno supone.", "Si falta, dilo."),
   ("Decir que falta información cuando sí está escrita.", "No se lee completo.", "Relee antes de decidir.")],
  ([E(f"Lee: «{PARQUE}» ¿Qué día permanece cerrado el parque?", "El lunes", "El texto dice «Los lunes permanece cerrado»."),
    E("Si un dato está escrito en el texto, ¿la información es suficiente o insuficiente?", "Suficiente", "Responde la pregunta."),
    E(f"Con este texto: «{PARQUE}» ¿el texto dice cuántos juegos hay?", "No", "Solo menciona que hay juegos infantiles.")],
   [E(f"Con «{PARQUE}» ¿alcanza la información para saber si se puede ir un lunes?", "Sí: ese día está cerrado", "El texto lo afirma."),
    E(f"Con «{PARQUE}» ¿alcanza para saber si se puede pescar en la laguna?", "No", "El texto no habla de pesca."),
    E(f"Con «{COM_C}» ¿alcanza para saber dónde será la feria?", "Sí, en el patio", "El texto lo dice.")],
   [arith("El parque abre de 9 a 18 horas. ¿Cuántas horas está abierto cada día de apertura?", "18-9", "Se resta la hora de apertura a la de cierre."),
    E(f"Con «{COM_C}» ¿alcanza para saber el valor de la entrada?", "Sí, es gratuita", "El texto dice «La entrada es gratuita»."),
    E(f"Con «{AVISO}» ¿alcanza para saber a qué hora pasará el camión el lunes?", "No", "Solo dice que el servicio se retomará el lunes.")],
   [E(f"Pregunta: ¿cuántos días a la semana abre el parque? Según «{PARQUE}», abre de martes a domingo. ¿Cuántos días son?", "6", "Martes, miércoles, jueves, viernes, sábado y domingo."),
    E(f"Para saber cuántas familias participarán en la feria, ¿alcanza «{COM_C}»?", "No", "Solo dice cuántos proyectos habrá.")],
   [E(f"Un lector dice que con «{PARQUE}» se sabe que el parque es seguro. ¿Alcanza la información?", "No", "El texto no habla de seguridad."),
    arith("Si el parque abre 6 días a la semana y cada día recibe 150 visitantes, ¿cuántos visitantes recibe en una semana?", "6*150", "Se multiplican los días por los visitantes.")]),
  [E(f"Quieres ir al parque con tu familia el domingo en la mañana. Con este texto: «{PARQUE}» ¿alcanza la información para saber si estará abierto?", "Sí, abre de 9 a 18 horas", "El texto da los horarios y dice que abre domingo.")],
  [E("Si el dato no está en el texto, ¿la información es insuficiente?", "Sí", "No responde la pregunta."),
   E("¿Se debe citar la frase que prueba la respuesta?", "Sí", "Es la evidencia."),
   E("¿Se puede completar lo que falta con suposiciones?", "No", "Hay que decir que falta.")],
  ("Lee: «El taller de pintura se hará el sábado en la biblioteca del barrio. Se recomienda llevar delantal. Los cupos son limitados.» Responde si alcanza la información para: 1) saber el día, 2) saber la hora, 3) saber si hay que pagar, 4) saber qué llevar. Cita la evidencia o escribe qué falta.",
   "1) Sí: «el sábado». 2) No: falta la hora. 3) No: falta saber si hay que pagar. 4) Sí: «llevar delantal».",
   ["decide bien si alcanza", "cita la evidencia", "indica el dato faltante"], ["cuatro respuestas"], ["suponer datos", "no citar evidencia"], "Subraya en el texto las frases que usaste como evidencia."),
  "Lee un afiche de tu barrio y anota una pregunta que sí responde y una que no.",
  "Escribe un aviso de cuatro líneas al que falte un dato importante y pide a alguien que lo descubra.")

L(OA7, 4,
  MAT,
  "Aprenderé a comparar la información sobre una misma noticia en distintas fuentes, notando qué coincide, qué cambia y por qué.",
  ["Identifico emisor y propósito.", "Distingo hecho y opinión."],
  ["Una misma noticia puede contarse de manera distinta según quién la cuente. Cada fuente tiene su emisor, su propósito y su audiencia. Por eso conviene comparar al menos dos fuentes: qué datos coinciden, cuáles cambian y qué palabras usa cada una para describir el hecho.",
   "Por ejemplo, la alcaldesa y un grupo de vecinos pueden hablar de la misma plaza. La alcaldesa destaca lo positivo (juegos y árboles nuevos) y los vecinos señalan problemas (faltan bancas y luz). Ambos dicen que la obra costó 50 millones de pesos: es un dato que coincide y por eso es más confiable. En cambio, el número de asistentes es distinto, y conviene preguntarse cómo se contó.",
   "Al comparar, usa una tabla con tres columnas: dato, fuente A, fuente B. Marca coincidencias y diferencias. Luego decide qué es lo más probable y qué falta verificar. Compara también el lenguaje: palabras como «reclaman» o «destacó» muestran la postura de la fuente."],
  [("fuente", "origen de la información"), ("coincidir", "estar de acuerdo en un dato"), ("postura", "manera de ver un tema"), ("verificar", "comprobar que algo es cierto")],
  [("Comparar datos", f"Lee: «{FUENTE_A}» y «{FUENTE_B}» ¿Qué dato coincide en ambas?",
    ["Reviso los datos de A y B.", "Costo: ambas dicen 50 millones de pesos.", "Ese dato coincide."],
    "El costo de la obra: 50 millones de pesos"),
   ("Comparar la postura", "En la misma comparación: ¿qué postura tiene cada fuente?",
    ["A es un comunicado de la alcaldesa: destaca lo positivo.", "B es de un grupo de vecinos: reclama.", "A destaca logros; B señala problemas."],
    "A destaca lo positivo y B señala los problemas")],
  [("Quedarse con la primera fuente que se lee.", "Se cree que una sola basta.", "Compara al menos dos fuentes."),
   ("Creer que dos datos distintos significan que una fuente miente.", "Puede haber distintas formas de contar.", "Pregunta cómo obtuvo cada fuente su dato.")],
  ([E(f"Lee: «{FUENTE_A}» ¿Cuántos vecinos asistieron según esta fuente?", "Cerca de 300", "Es lo que dice el comunicado."),
    E(f"Lee: «{FUENTE_B}» ¿Cuántas personas asistieron según este grupo?", "120", "Es la cifra que da el grupo de vecinos."),
    E("¿Un dato que coincide en dos fuentes es más confiable?", "Sí", "Al coincidir, hay más respaldo.")],
   [E(f"Compara: «{FUENTE_A}» y «{FUENTE_B}». ¿Cuál fuente menciona que faltan bancas y luz?", "La fuente B", "Es el reclamo de los vecinos."),
    E(f"Compara: «{FUENTE_A}» y «{FUENTE_B}». ¿Cuál fuente destaca que hay juegos y árboles nuevos?", "La fuente A", "Es el comunicado de la alcaldesa."),
    E(f"Compara: «{FUENTE_A}» y «{FUENTE_B}». ¿Ambas fuentes coinciden en el costo de la obra?", "Sí", "Ambas dicen 50 millones de pesos.")],
   [arith("La fuente A dice cerca de 300 asistentes y la B dice 120. ¿Cuántos asistentes de diferencia hay entre las cifras?", "300-120", "Se resta la cifra menor de la mayor."),
    E("La fuente B dice «según el grupo». ¿Qué indica esa expresión: que es información del grupo y no un dato comprobado o que es una mentira?", "Que es información del grupo y no un dato comprobado", "Señala de dónde viene la cifra."),
    arith("Si de los 50 millones de pesos que costó la obra, 20 millones se gastaron en juegos, ¿cuántos millones se gastaron en lo demás?", "50-20", "Se resta lo gastado en juegos del costo total.")],
   [E("Un lector dice: «La fuente A es mejor porque es la alcaldesa». ¿Es un criterio suficiente?", "No", "Hay que verificar con criterios, no solo por quién habla."),
    E("Si quieres saber cuántas personas asistieron realmente, ¿qué haces: buscar una tercera fuente o elegir la cifra que más te gusta?", "Buscar una tercera fuente", "Compara más datos.")],
   [E("Una fuente dice «vecinos reclaman» y otra «la alcaldesa destacó». ¿Qué muestran esas palabras: la postura de cada fuente o que ambas piensan igual?", "La postura de cada fuente", "Cada verbo expresa una mirada distinta."),
    E("Si dos fuentes coinciden en el costo pero difieren en los asistentes, ¿qué conclusión es más razonable: el costo es más confiable que el número de asistentes o ambos son igual de dudosos?", "El costo es más confiable que el número de asistentes", "El costo coincide en ambas fuentes.")]),
  [E("Lees dos noticias sobre un partido: una dice que ganó el equipo local por 2 a 1 y otra dice 3 a 1. ¿Qué haces: buscar una tercera fuente o quedarte con la que más te guste?", "Buscar una tercera fuente", "Los datos no coinciden.")],
  [E("¿Conviene comparar al menos dos fuentes?", "Sí", "Así se detectan diferencias."),
   E("¿Un dato que coincide en ambas fuentes es más confiable?", "Sí", "Tiene más respaldo."),
   E("¿Las palabras de un texto pueden mostrar su postura?", "Sí", "Revelan cómo ve el hecho.")],
  ("Compara estas dos fuentes sobre una misma noticia. Fuente A: «El club deportivo informó que ayer se inauguró la cancha nueva con 200 asistentes.» Fuente B: «Socios del club dicen que la cancha nueva se inauguró con pocos asistentes y sin baños habilitados.» Haz una tabla de tres columnas con los datos y escribe: qué coincide, qué cambia y qué verificarías.",
   "Coincide: se inauguró la cancha nueva. Cambia: A dice 200 asistentes y B dice pocos; A no menciona baños y B dice que no están habilitados. Verificaría la cantidad de asistentes y el estado de los baños en una tercera fuente.",
   ["identifica lo que coincide", "identifica lo que cambia", "propone qué verificar"], ["tabla de tres columnas", "conclusión escrita"], ["quedarse con una fuente", "no indicar qué verificar"], "Subraya con un color lo que coincide y con otro lo que cambia."),
  "Busca dos noticias sobre el mismo hecho y compara un dato que coincida y uno distinto.",
  "Escribe dos versiones breves de un mismo hecho: una positiva y una crítica, usando palabras distintas.")

L(OA7, 5,
  MAT,
  "Aprenderé a producir mi propia evaluación escrita de un texto, indicando su emisor, propósito, audiencia y si la información alcanza.",
  ["Evalúo emisor y propósito.", "Compruebo si la información es suficiente."],
  ["Una evaluación escrita de un texto tiene cuatro partes: 1) emisor y propósito; 2) destinatario; 3) si la información es suficiente para responder una pregunta; 4) una recomendación para verificar o completar la información. Cada parte debe tener evidencia del texto.",
   "Por ejemplo: «El texto lo emite la dirección del colegio y su propósito es informar. Se dirige a las familias. La información alcanza para saber el día, la hora y el lugar, pero no cómo inscribirse. Recomiendo confirmar la inscripción con la dirección». Observa cómo cada afirmación se apoya en el texto.",
   "Usa conectores como «porque», «sin embargo» y «por eso», y verbos como «informa», «persuade», «se dirige a». Evita decir solo «es bueno» o «es malo»: una evaluación crítica explica por qué la información es confiable o no."],
  [("evaluación", "juicio fundamentado sobre algo"), ("recomendación", "consejo sobre lo que conviene hacer"), ("conector", "palabra que une ideas, como «porque» o «sin embargo»"), ("confiable", "que merece confianza")],
  [("Armar una evaluación", f"Texto: «{AVISO}» Escribe la primera parte de la evaluación.",
    ["Emisor: Municipalidad de Valle Verde.", "Propósito: informar un cambio en la recolección.", "Escribo: «El texto lo emite la municipalidad y su propósito es informar»."],
    "El texto lo emite la municipalidad y su propósito es informar"),
   ("Completar con recomendación", "Un texto no dice el precio de la entrada. ¿Qué recomendación agregas?",
    ["Veo que falta un dato.", "Pienso a quién preguntar.", "Escribo: «Recomiendo confirmar el precio con los organizadores»."],
    "Recomiendo confirmar el precio con los organizadores")],
  [("Evaluar solo con «es bueno» o «es malo».", "No se explican razones.", "Explica por qué con evidencia."),
   ("Olvidar la recomendación final.", "Se queda en describir.", "Cierra diciendo cómo verificar o completar.")],
  ([E("¿Cuántas partes tiene la evaluación que se explica en esta clase?", "4", "Emisor y propósito, destinatario, suficiencia y recomendación."),
    E("¿Qué conector sirve para dar una razón: «porque» o «aunque»?", "Porque", "Introduce la razón."),
    E("¿Una evaluación debe tener evidencia del texto?", "Sí", "Respalda cada afirmación.")],
   [E(f"Con «{COM_C}» ¿cuál es una buena primera frase: «El texto lo emite la dirección y su propósito es informar» o «El texto es bonito»?", "«El texto lo emite la dirección y su propósito es informar»", "Nombra emisor y propósito."),
    E(f"Con «{PARQUE}» ¿qué recomendación corresponde si falta el precio: «confirmar el precio en la administración» o «ir sin averiguar»?", "«Confirmar el precio en la administración»", "Completa el dato faltante."),
    E("¿Con qué verbo se describe lo que hace un texto que da datos: «informa» o «ladra»?", "Informa", "Es el verbo adecuado.")],
   [arith("Una evaluación tiene 4 partes y cada una necesita 2 oraciones. ¿Cuántas oraciones tiene?", "4*2", "Se multiplican partes por oraciones."),
    E(f"Con «{PUBLI}» ¿qué escribirías en la parte de propósito: «persuadir a comprar» o «instruir cómo cocinar»?", "«Persuadir a comprar»", "Es lo que busca el aviso."),
    E(f"Con «{OPI_D}» ¿qué escribirías en la parte de suficiencia: «no alcanza para saber horarios de la feria» o «alcanza para saber el costo de la entrada»?", "«No alcanza para saber horarios de la feria»", "La publicación no menciona horarios.")],
   [E("Una evaluación dice: «El aviso es malo». Otra: «El aviso no dice la hora, por eso falta información». ¿Cuál es más crítica?", "La segunda", "Explica la razón."),
    E("Una evaluación termina con una recomendación para verificar. ¿Es útil?", "Sí", "Orienta cómo completar la información.")],
   [E(f"Con «{FUENTE_B}» ¿qué recomendación es mejor: «consultar otra fuente sobre cuántas personas asistieron» o «creer la cifra sin más»?", "«Consultar otra fuente sobre cuántas personas asistieron»", "Verifica un dato dudoso."),
    arith("Evalúas 3 textos y escribes 4 oraciones por texto. ¿Cuántas oraciones escribes?", "3*4", "Se multiplican textos por oraciones.")]),
  [E("Tu curso debe evaluar un aviso antes de pegarlo en el diario mural. ¿Qué incluyes en la evaluación: emisor, propósito, destinatario, suficiencia y recomendación, o solo si te gusta?", "Emisor, propósito, destinatario, suficiencia y recomendación", "Son las partes de una evaluación crítica.")],
  [E("¿La evaluación incluye una recomendación?", "Sí", "Sirve para verificar o completar."),
   E("¿«Es bueno» alcanza como evaluación?", "No", "Falta explicar por qué."),
   E("¿Un conector une ideas?", "Sí", "Ayuda a dar razones.")],
  ("Escribe una evaluación de cuatro oraciones sobre este texto: «Se invita a los niños de 5.º y 6.º a participar en un campeonato de ajedrez el próximo sábado en el gimnasio. Inscripciones al correo del colegio. Habrá premios.» Debes nombrar emisor (probablemente el colegio), propósito, destinatario, si falta un dato y qué recomiendas.",
   "El texto probablemente lo emite el colegio y su propósito es invitar. Se dirige a niños de 5.º y 6.º. La información alcanza para saber el día y el lugar, pero no la hora ni el costo. Recomiendo preguntar esos datos al colegio antes de inscribirse.",
   ["emisor y propósito", "destinatario", "suficiencia con evidencia", "recomendación"], ["evaluación de cuatro oraciones"], ["evaluación sin razones", "no indicar qué falta"], "Subraya en el texto la evidencia de cada parte."),
  "Evalúa un aviso real que encuentres en tu barrio con las cuatro partes.",
  "Intercambia tu evaluación con otra persona y comparen qué datos faltantes detectaron.")

L(OA7, 6,
  MAT,
  "Aprenderé a revisar mi evaluación de un texto para que sea clara y justa para quien la lea, corrigiendo datos, razones y recomendaciones.",
  ["Escribo evaluaciones con evidencia.", "Comparo fuentes."],
  ["Revisar una evaluación crítica es comprobar que lo que afirmas es correcto y está respaldado. Pregúntate: ¿nombré al emisor correcto?, ¿el propósito que dije se ve en el texto?, ¿cité datos exactos?, ¿mi recomendación es posible de hacer? y ¿está escrito con respeto?",
   "Piensa en quién leerá tu evaluación. Si es para el diario mural, usa frases claras y completas. Si es para la dirección, puedes ser más detallado. Si es para niños pequeños, usa frases cortas. En todos los casos, evita acusar a una persona sin evidencia: critica el texto, no a quien lo escribió.",
   "Algunos errores frecuentes son: confundir el emisor con el destinatario, citar un dato que el texto no dice, mezclar opinión con hecho o recomendar algo imposible. Corrige cada uno volviendo al texto."],
  [("revisar", "volver a leer para mejorar un texto"), ("justo", "que se apoya en razones y trata bien a las personas"), ("acusar", "decir que alguien hizo algo malo"), ("posible", "que se puede hacer")],
  [("Corregir un dato", f"Evaluación de «{COM_C}»: «La feria será el jueves a las 17 horas.» ¿Qué corriges?",
    ["Busco la hora en el texto.", "El texto dice las 15 horas.", "Corrijo: la feria será a las 15 horas."],
    "La feria será a las 15 horas"),
   ("Corregir una acusación", "Una evaluación dice: «El que escribió este aviso es un mentiroso». ¿Cómo la reescribes?",
    ["Pregunto qué evidencia hay de mentira.", "No hay evidencia; solo falta un dato.", "Escribo: «El aviso no informa el precio, por eso falta información»."],
    "El aviso no informa el precio, por eso falta información")],
  [("Criticar a la persona y no al texto.", "Se confunde evaluar con ofender.", "Critica lo que el texto dice o no dice."),
   ("Recomendar algo imposible.", "No se piensa en lo que se puede hacer.", "Propón acciones realistas.")],
  ([E("Al revisar una evaluación, ¿debes comprobar los datos con el texto?", "Sí", "Un dato errado debilita la evaluación."),
    E("¿Una evaluación crítica debe criticar al texto o a la persona que lo escribió?", "Al texto", "Se evalúan sus datos y claridad."),
    E("¿Una recomendación debe ser posible de hacer?", "Sí", "Si no, no sirve.")],
   [E(f"Sobre «{PARQUE}», alguien escribe: «El parque abre de lunes a domingo». ¿Qué corriges?", "Abre de martes a domingo", "El lunes está cerrado."),
    E("Un compañero escribe una evaluación llena de ofensas. ¿Qué le sugieres: quitar las ofensas y explicar con razones o dejarlo?", "Quitar las ofensas y explicar con razones", "Una evaluación debe ser respetuosa."),
    E("¿Mezclar opinión y hecho sin distinguirlos es un error frecuente?", "Sí", "Se debe diferenciar lo comprobable de lo personal.")],
   [arith("Una evaluación tiene 12 oraciones y quitas 3 repetidas. ¿Cuántas quedan?", "12-3", "Se restan las repetidas."),
    E(f"Lee: «{COM_C}» Revisa: «El emisor del comunicado son las familias». ¿Está bien?", "No", "El emisor es la dirección y las familias son destinatarias."),
    E(f"Lee: «{AVISO}» Una recomendación dice «Llamar a la oficina de aseo para pedir más información». ¿Es posible de hacer?", "Sí", "El aviso invita a llamar a esa oficina.")],
   [E("Un compañero dice que tu evaluación es larga y enredada. ¿Qué haces: dividir las frases y ordenar las ideas o alargarlas más?", "Dividir las frases y ordenar las ideas", "Así mejora la claridad."),
    E("Tu evaluación será leída por niños de 2.º básico. ¿Qué usas: frases cortas y palabras simples o términos técnicos?", "Frases cortas y palabras simples", "Se adapta al lector.")],
   [E("Una evaluación dice: «La fuente A miente». ¿Qué falta para sostenerlo: evidencia de que el dato es falso o nada?", "Evidencia de que el dato es falso", "Sin evidencia es acusación."),
    arith("Tu lista de revisión tiene 5 puntos y cumples 4. ¿Cuántos faltan?", "5-4", "Se resta lo cumplido del total.")]),
  [E("Antes de pegar tu evaluación en el diario mural, notas que acusa a alguien sin evidencia. ¿Qué haces: cambiar la acusación por una crítica al texto o dejarla?", "Cambiar la acusación por una crítica al texto", "Debe estar respaldada.")],
  [E("¿Se debe criticar al texto o a la persona?", "Al texto", "Así se evalúa de forma justa."),
   E("¿Revisar incluye corregir datos?", "Sí", "Cada dato debe coincidir con el texto."),
   E("¿Una recomendación posible es mejor que una imposible?", "Sí", "Se puede realizar.")],
  ("Revisa esta evaluación y reescríbela mejor. Texto: «Se informa que el taller de teatro será el miércoles a las 16 horas en el gimnasio. Cupos limitados.» Evaluación: «El texto lo hace la dirección y es un engaño. No dice cuándo es. El taller es en el patio.» Corrige tres problemas y escribe una versión de cuatro oraciones.",
   "Problemas: acusa de engaño sin evidencia, dice que no informa cuándo (sí dice miércoles 16 horas), dice patio (es el gimnasio). Versión: «El texto informa sobre un taller de teatro. Dice que será el miércoles a las 16 horas en el gimnasio. No dice el costo ni cómo inscribirse. Recomiendo preguntar a los organizadores.»",
   ["corrige los datos", "elimina la acusación", "agrega una recomendación posible"], ["versión final de cuatro oraciones"], ["mantener datos erróneos", "dejar la acusación"], "Compara cada dato de tu versión con el texto original."),
  "Pide a alguien que lea tu evaluación y diga si es justa y clara.",
  "Escribe dos versiones de la misma evaluación: una para niños pequeños y otra para la dirección.")

L(OA7, 7,
  MAT,
  "Aprenderé a transferir lo aprendido a un conjunto nuevo de textos: evaluar emisor, propósito, destinatario, suficiencia y fuentes en una situación distinta.",
  ["Evalúo textos con criterios.", "Comparo fuentes."],
  ["Transferir es aplicar a una situación nueva lo que ya sabes. Cuando recibas textos distintos sobre un mismo hecho, sigue el mismo recorrido: 1) identifica emisor, propósito y destinatario de cada uno; 2) revisa si entregan información suficiente para tu pregunta; 3) compara los datos entre fuentes; 4) decide qué creer y qué verificar.",
   "Por ejemplo, para la Feria de Ciencias hay un comunicado de la dirección y una publicación de una apoderada. El comunicado informa fecha, hora y lugar; la publicación expresa una opinión sobre la feria. Si quieres saber a qué hora es la feria, el comunicado sirve. Si quieres saber si les gustó, la publicación sirve, pero es una opinión personal.",
   "Una buena evaluación no se queda en un texto: usa el más adecuado para cada pregunta y reconoce las limitaciones de cada uno. A veces hay que usar ambos; otras, buscar una tercera fuente."],
  [("transferir", "aplicar lo aprendido a una situación nueva"), ("limitación", "aquello que un texto no puede responder"), ("adecuado", "que sirve para lo que se necesita"), ("recorrido", "serie de pasos")],
  [("Elegir el texto adecuado", f"Textos: «{COM_C}» y «{OPI_D}». Si quieres saber la hora de la feria, ¿qué texto usas?",
    ["Busco quién entrega datos de hora.", "El comunicado de la dirección dice 15 horas.", "Uso el comunicado."],
    "El comunicado de la dirección"),
   ("Reconocer la limitación", "En la misma situación: ¿qué no te dice la publicación de la apoderada?",
    ["Reviso lo que dice: que estuvo espectacular.", "No da hora, lugar ni cantidad de proyectos.", "No entrega datos comprobables."],
    "No entrega hora, lugar ni cantidad de proyectos")],
  [("Usar un solo texto para todas las preguntas.", "Se cree que uno basta.", "Elige el más adecuado a cada pregunta."),
   ("Tratar una opinión como un dato.", "Se confunden.", "Distingue lo comprobable de lo personal.")],
  ([E(f"Lee: «{COM_C}» ¿Cuántos proyectos participarán?", "24", "Es un dato del comunicado."),
    E(f"Lee: «{OPI_D}» ¿Es un dato comprobable o una opinión que la feria estuvo «espectacular»?", "Una opinión", "Expresa una valoración."),
    E("¿Quién emite el comunicado de la feria?", "La dirección del colegio", "Está en el encabezado.")],
   [E(f"Lee: «{COM_C}» y «{OPI_D}». Si quieres saber si la entrada tiene costo, ¿qué texto usas?", "El comunicado", "Dice que la entrada es gratuita."),
    E(f"Lee: «{COM_C}» y «{OPI_D}». Si quieres saber cómo se sintió una apoderada, ¿qué texto sirve más?", "La publicación de la apoderada", "Expresa una impresión personal."),
    E(f"Según este comunicado: «{COM_C}» ¿dónde será la feria?", "En el patio", "El texto lo indica.")],
   [arith("Si cada uno de los 24 proyectos lo presentan 2 estudiantes, ¿cuántos estudiantes presentan en total?", "24*2", "Se multiplica por los estudiantes de cada proyecto."),
    E(f"Lee: «{COM_C}» y «{OPI_D}». Si quieres saber cuántas personas asistieron a la feria, ¿alcanza alguno de los dos textos?", "No", "Ninguno dice cuántas personas asistieron."),
    E(f"Lee: «{COM_C}» y «{OPI_D}». ¿Qué texto es más confiable para datos de hora y lugar: el comunicado o la publicación de la apoderada?", "El comunicado", "Lo emite la institución organizadora.")],
   [E(f"Lee: «{OPI_D}» Una compañera dice: «La publicación prueba que fue la mejor feria». ¿Es una conclusión adecuada?", "No", "Es una opinión personal, no una prueba."),
    E(f"Lee: «{COM_C}» ¿Qué debes hacer para saber la cantidad de asistentes: buscar otra fuente o suponer?", "Buscar otra fuente", "El comunicado no lo informa.")],
   [E("En un nuevo caso recibes un comunicado de la municipalidad y una publicación de un vecino. ¿Aplicas el mismo recorrido?", "Sí", "Es lo que significa transferir."),
    arith("Llegaron 3 textos por día durante 5 días. ¿Cuántos textos recibiste?", "3*5", "Se multiplican textos por días.")]),
  [E("Para organizar un paseo, recibes un aviso del colegio con horarios y un comentario de un compañero que dice «será genial». ¿Cuál usas para saber la hora de salida?", "El aviso del colegio", "Entrega datos comprobables.")],
  [E("¿Transferir es aplicar lo aprendido a una situación nueva?", "Sí", "Esa es su definición."),
   E("¿Una opinión sirve para conocer lo que alguien siente?", "Sí", "Pero no para datos comprobables."),
   E("¿A veces hay que usar más de un texto?", "Sí", "Cada uno responde algo distinto.")],
  ("Recibes estos textos sobre una visita al museo. Texto 1 (de la dirección): «La visita al museo será el martes. Salida a las 9 horas, regreso a las 13 horas. Costo: 2.000 pesos por estudiante.» Texto 2 (de un compañero): «¡Va a ser lo mejor del año, el museo es increíble!» Responde: 1) ¿cuál texto usas para la hora de salida?, 2) ¿cuál para saber cuánto cuesta?, 3) ¿cuál expresa una opinión?, 4) ¿qué dato falta para el apoderado?",
   "1) El texto 1. 2) El texto 1: 2.000 pesos. 3) El texto 2. 4) Falta saber qué llevar, si hay almuerzo o cómo se autoriza la salida.",
   ["elige el texto adecuado en cada caso", "reconoce opinión", "indica un dato faltante coherente"], ["cuatro respuestas"], ["usar el texto 2 para datos", "no reconocer lo que falta"], "Subraya en cada texto la frase que justifica tu elección."),
  "Aplica el recorrido a dos mensajes que recibas en tu casa sobre un mismo tema.",
  "Escribe dos textos de un mismo hecho: uno informativo y otro de opinión, y señala sus diferencias.")
